// dev diag: remote control over the USB-Serial-JTAG console, read straight
// from the RX FIFO so the ROM printing on the TX side is left alone.
//   k XX      press and release PC-98 key XX (hex)
//   d XX/u XX key down / up
//   m DX DY B mouse move (decimal) and buttons (bit0 L, bit1 R)
//   s         send the screen: SHOT w h, then one line of RGB332 hex a row
#if defined(PC98_NEWCPU) && PC98_NEWCPU == 1
extern "C" void pc98_adapt_prof(unsigned long long *ins, unsigned *runs, unsigned *slow);
#endif
extern "C" volatile unsigned long long g_prof_cpu_cyc, g_prof_cpu_clk, g_prof_cpu_ins;   // machine.c
extern "C" volatile unsigned long long g_prof_grph, g_prof_text, g_prof_comp;   // render.c
extern "C" volatile long long g_prof_snd;   // machine.c (us)
static void remote_screen(void) {
    int w = 0, h = 0, stride = 0;
    const uint16_t *src = (const uint16_t *)lcd_last_frame(&w, &h, &stride);
    if (!src) {
        ets_printf("SHOT 0 0\n");
        return;
    }
    ets_printf("SHOT %d %d\n", w, h);
    static const char hx[] = "0123456789abcdef";
    static char line[2 + 640 * 2 + 2];
    for (int y = 0; y < h; y++) {
        const uint16_t *s = src + (size_t)y * stride;
        int n = 0;
        line[n++] = 'R';
        line[n++] = ' ';
        for (int x = 0; x < w && x < 640; x++) {
            const uint16_t p = s[x];
            const uint8_t c = (uint8_t)(((p >> 13) << 5) | (((p >> 8) & 7) << 2) | ((p >> 3) & 3));
            line[n++] = hx[c >> 4];
            line[n++] = hx[c & 15];
        }
        line[n++] = '\n';
        line[n] = 0;
        ets_printf("%s", line);
    }
    ets_printf("SHOTEND\n");
}

